from pathlib import Path
import re

p = Path("src/components/TracksPlayer.jsx")
s = p.read_text()

# Remove any temporary test text left by earlier iterations.
s = s.replace('<div className="nyxtryp-auto-test">ПРИВЕТ</div>', '')
s = s.replace('ПРИВЕТ', '')

# Replace the complete stereo meter markup, while leaving the player logic untouched.
marker = '          {!isMobile && (\n            <div className="tracks-mc-vu">'
start = s.find(marker)
if start < 0:
    raise SystemExit("L/R meter markup not found")
end = s.find('          )}', start)
if end < 0:
    raise SystemExit("L/R meter markup end not found")
end += len('          )}')

new_block = '''          {!isMobile && (\n            <div className="tracks-mc-vu">\n              {[['L', leftVU], ['R', rightVU]].map(([channel, value]) => {\n                const displayValue = Math.max(-60, Math.min(3, value))\n                const normalized = (displayValue + 60) / 63\n                const angle = -48 + normalized * 96\n\n                return (\n                  <div className="tracks-mc-meter" key={channel}>\n                    <div className="tracks-mc-window">\n                      <svg\n                        className="tracks-mc-gauge"\n                        viewBox="0 0 420 178"\n                        preserveAspectRatio="xMidYMid meet"\n                        aria-label={`${channel} analog VU meter`}\n                      >\n                        <defs>\n                          <linearGradient id={`vu-glass-${channel}`} x1="0" y1="0" x2="0" y2="1">\n                            <stop offset="0" stopColor="#76dfff" />\n                            <stop offset="0.48" stopColor="#2baee8" />\n                            <stop offset="1" stopColor="#0874ad" />\n                          </linearGradient>\n                          <radialGradient id={`vu-glow-${channel}`} cx="50%" cy="56%" r="75%">\n                            <stop offset="0" stopColor="#d4f7ff" stopOpacity=".28" />\n                            <stop offset=".58" stopColor="#75d7ff" stopOpacity=".08" />\n                            <stop offset="1" stopColor="#001521" stopOpacity="0" />\n                          </radialGradient>\n                          <filter id={`vu-soft-${channel}`} x="-30%" y="-30%" width="160%" height="160%">\n                            <feGaussianBlur stdDeviation="2" />\n                          </filter>\n                        </defs>\n\n                        <rect x="1.5" y="1.5" width="417" height="175" rx="3" fill="#05090c" stroke="#26353d" strokeWidth="3" />\n                        <rect x="8" y="8" width="404" height="162" rx="1.5" fill={`url(#vu-glass-${channel})`} />\n                        <rect x="8" y="8" width="404" height="162" rx="1.5" fill={`url(#vu-glow-${channel})`} />\n                        <rect x="9" y="9" width="402" height="160" fill="none" stroke="rgba(255,255,255,.13)" />\n\n                        <!-- Wide, shallow analog arc -->\n                        <path d="M52 124 Q210 77 368 124" fill="none" stroke="rgba(2,38,61,.88)" strokeWidth="2.5" />\n                        <path d="M52 122 Q210 75 368 122" fill="none" stroke="rgba(218,247,255,.18)" strokeWidth="1" />\n\n                        {Array.from({ length: 13 }, (_, i) => {\n                          const t = i / 12\n                          const x = 52 + 316 * t\n                          const y = 124 - 49 * (4 * t * (1 - t))\n                          const slope = 196 * (t - 0.5)\n                          const norm = Math.hypot(1, slope)\n                          const nx = -slope / norm\n                          const ny = -1 / norm\n                          const major = i % 2 === 0\n                          const len = major ? 10 : 5\n                          return (\n                            <g key={i}>\n                              <line\n                                x1={x - nx * 1}\n                                y1={y - ny * 1}\n                                x2={x + nx * len}\n                                y2={y + ny * len}\n                                stroke="rgba(2,35,56,.94)"\n                                strokeWidth={major ? 1.7 : 1}\n                              />\n                              {major && (\n                                <text\n                                  x={x + nx * 17}\n                                  y={y + ny * 17 + 3}\n                                  textAnchor="middle"\n                                  fill="rgba(2,33,53,.96)"\n                                  fontSize="10"\n                                  fontFamily="Arial, sans-serif"\n                                >\n                                  {[-20, -10, 0, 3, 6, 9, 12][i / 2]}\n                                </text>\n                              )}\n                            </g>\n                          )\n                        })}\n\n                        <text x="210" y="31" textAnchor="middle" fill="rgba(2,34,54,.96)" fontSize="10" fontWeight="700" fontFamily="Arial, sans-serif" letterSpacing="2.4">McINTOSH</text>\n                        <text x="210" y="45" textAnchor="middle" fill="rgba(2,34,54,.90)" fontSize="7.5" fontFamily="Arial, sans-serif" letterSpacing="1.5">STEREO POWER OUTPUT</text>\n\n                        <line x1="210" y1="126" x2="210" y2="51" stroke="rgba(220,249,255,.30)" strokeWidth="4" strokeLinecap="round" filter={`url(#vu-soft-${channel})`} />\n                        <g transform={`rotate(${angle} 210 126)`}>\n                          <line x1="210" y1="126" x2="210" y2="48" stroke="#f4fbff" strokeWidth="2" strokeLinecap="round" />\n                          <line x1="210" y1="126" x2="210" y2="54" stroke="rgba(22,60,83,.88)" strokeWidth=".8" strokeLinecap="round" />\n                        </g>\n                        <circle cx="210" cy="126" r="5" fill="#d9e8ee" stroke="#17394d" strokeWidth="1.7" />\n                        <circle cx="210" cy="126" r="1.5" fill="#07131a" />\n\n                        <text x="27" y="157" fill="rgba(2,31,49,.88)" fontSize="8" fontFamily="Arial, sans-serif" fontWeight="700">{channel}</text>\n                      </svg>\n                    </div>\n                  </div>\n                )\n              })}\n            </div>\n          )}'''

s = s[:start] + new_block + s[end:]

# Replace only the meter CSS. The existing @media section stays untouched.
css_start = s.find('        .tracks-mc-vu {')
if css_start < 0:
    raise SystemExit("meter CSS start not found")
css_end = s.find('        @media (max-width: 600px) {', css_start)
if css_end < 0:
    raise SystemExit("meter CSS end not found")

new_css = '''        .tracks-mc-vu {\n          display: flex;\n          width: 100%;\n          gap: 14px;\n          justify-content: center;\n          align-items: stretch;\n          padding: 2px 0 4px;\n        }\n\n        .tracks-mc-meter {\n          flex: 1 1 0;\n          min-width: 0;\n        }\n\n        .tracks-mc-window {\n          width: 100%;\n          overflow: hidden;\n          border-radius: 3px;\n          background: #05090c;\n          border: 1px solid rgba(190,214,228,.42);\n          box-shadow: inset 0 0 0 1px rgba(0,0,0,.95), 0 5px 15px rgba(0,0,0,.28);\n        }\n\n        .tracks-mc-gauge {\n          width: 100%;\n          height: auto;\n          display: block;\n          aspect-ratio: 420 / 178;\n        }\n\n'''

s = s[:css_start] + new_css + s[css_end:]
p.write_text(s)
print("NYXTRYP: installed refined stereo analog VU meter")